<section class="form-section"><div class="form-section-heading"><p class="eyebrow">Coverage</p><h2>Choose who and where.</h2></div><div class="selection-block"><div class="selection-heading"><span class="form-field-label">Campuses</span><label class="select-all"><input type="checkbox" data-select-all="event-campuses" @checked(count(old('campus_ids', $selectedCampuses ?? [])) === $campuses->count() && $campuses->count() > 0)><span>Select all campuses</span></label><small>Select the campuses connected to this event.</small></div><div class="choice-grid" data-select-group="event-campuses">@foreach ($campuses as $campus)<label class="choice-item"><input type="checkbox" name="campus_ids[]" value="{{ $campus->id }}" @checked(in_array($campus->id, old('campus_ids', $selectedCampuses ?? [])))><span>{{ $campus->name }}</span></label>@endforeach</div></div><div class="selection-block"><div class="selection-heading"><span class="form-field-label">Schools</span><label class="select-all"><input type="checkbox" data-select-all="event-schools" @checked(count(old('school_ids', $selectedSchools ?? [])) === $schools->count() && $schools->count() > 0)><span>Select all schools</span></label><small>Select the schools connected to this event.</small></div><div class="choice-grid" data-select-group="event-schools">@foreach ($schools as $school)<label class="choice-item"><input type="checkbox" name="school_ids[]" value="{{ $school->id }}" @checked(in_array($school->id, old('school_ids', $selectedSchools ?? [])))><span>{{ $school->name }}</span></label>@endforeach</div></div><script>document.querySelectorAll('[data-select-all]').forEach(selectAll => { const group = document.querySelector(`[data-select-group="${selectAll.dataset.selectAll}"]`); if (!group) return; const choices = group.querySelectorAll('input[type="checkbox"]'); selectAll.addEventListener('change', () => choices.forEach(choice => choice.checked = selectAll.checked)); choices.forEach(choice => choice.addEventListener('change', () => { selectAll.checked = Array.from(choices).every(item => item.checked); })); });</script></section>
